# Disable Diagnostic Data Collection Write-Host "Disabling diagnostic data collection..." -ForegroundColor Cyan # Set diagnostic data to minimal (security only) - level 0 Set-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\DataCollection" -Name "AllowTelemetry" -Value 0 -Type DWord -Force -ErrorAction Stop Set-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection" -Name "AllowTelemetry" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue # Disable Diagnostic Policy Service Stop-Service -Name "DPS" -Force -ErrorAction SilentlyContinue Set-Service -Name "DPS" -StartupType Disabled -ErrorAction SilentlyContinue # Disable connected user experiences Set-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection" -Name "DoNotShowFeedbackNotifications" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue # Disable error reporting Set-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Error Reporting" -Name "Disabled" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue Write-Host "Diagnostic data collection has been set to minimal (security only)." -ForegroundColor Green